/**
 * This utility function creates a log function to be used within a Neon widget.  The API on the log function
 * is identical to console.log, with the one difference that it won't log anything until it is turned on
 * in localStorage.
 *
 * Example: window.neonToolkits['neon-0_2_0-logger'].setLoggerStatus('input-widgets', true);
 *
 * @param key - The key to turn the logger on and off. The key in the example above is: 'input-widgets'
 * @param prependText - Text that will be prepended to every call to the generated log function.
 * @returns a static log function that can be called just like console.log.
 */
export declare function getLogFunction(key: string, prependText?: string): (...args: Array<any>) => void;
